-- Nacre: Hyprland visual layer. Generated by rice-render from palette.toml.
-- Loaded from hyprland.lua via ~/.local/share/rice/active/hypr.lua.

local iridescent = {
    colors = { {{ gradient.stops | closed | hypr(ff) | quote | join(", ") }} },
    angle  = {{ gradient.angle }},
}

-- the ice edge: a bright near-white stop where light catches the top-left
-- corner, then the iridescence, then white again; it turns with the loop
local rim = {
    colors = { "rgba(ffffffee)", "{{ colors.rose | hypr(ff) }}", "{{ colors.sky | hypr(ff) }}",
               "{{ colors.mint | hypr(ff) }}", "{{ colors.orchid | hypr(ff) }}", "rgba(ffffffcc)" },
    angle  = 45,
}
-- unfocused panes: white along the top fading to lilac, still glass
local pane = {
    colors = { "rgba(ffffff99)", "{{ colors.lilac | hypr(55) }}" },
    angle  = 90,
}

hl.config({
    general = {
        gaps_in     = {{ shape.gaps_in }},
        gaps_out    = {{ shape.gaps_out }},
        border_size = {{ shape.border }},
        col = {
            active_border   = rim,
            inactive_border = pane,
        },
    },

    decoration = {
        rounding         = {{ shape.window }},
        rounding_power   = {{ shape.rounding_power }},
        active_opacity   = 1.0,
        inactive_opacity = {{ opacity.inactive }},
        dim_inactive     = false,

        -- frost: wide and a little darker and crisper than the default, with
        -- the wallpaper's colour pushed up so the glass reads as tinted ice
        blur = {
            enabled           = true,
            size              = 10,
            passes            = 3,
            noise             = 0.035,
            contrast          = 1.15,
            brightness        = 0.92,
            vibrancy          = 0.4,
            vibrancy_darkness = 0.25,
            popups            = true,
            xray              = false,
        },

        -- cool ice-blue shadows, never black; softer on inactive windows
        shadow = {
            enabled        = true,
            range          = 34,
            render_power   = 3,
            color          = "{{ roles.shadow | hypr(0.30) }}",
            color_inactive = "{{ roles.shadow | hypr(0.18) }}",
        },
    },

    group = {
        col = {
            border_active   = rim,
            border_inactive = pane,
        },
        groupbar = {
            enabled           = true,
            height            = 18,
            indicator_height  = 0,
            gradients         = true,
            rounding          = 9,
            gradient_rounding = 9,
            round_only_edges  = false,
            gradient_round_only_edges = false,
            font_family       = "{{ fonts.ui }}",
            font_size         = 11,
            font_weight_active   = {{ fonts.weight_strong }},
            font_weight_inactive = {{ fonts.weight }},
            text_color        = "{{ roles.fg | hypr(ff) }}",
            text_color_inactive = "{{ roles.muted | hypr(ff) }}",
            col = {
                active   = iridescent,
                inactive = "{{ roles.surface | hypr(cc) }}",
            },
        },
    },

    animations = { enabled = true },
})

---------------------------------------------------------------------------
-- Motion: bloom in, sink out, settle when moving
---------------------------------------------------------------------------
hl.curve("bloom",  { type = "bezier", points = { { {{ motion.bloom.0 }}, {{ motion.bloom.1 }} },  { {{ motion.bloom.2 }}, {{ motion.bloom.3 }} } } })
hl.curve("settle", { type = "bezier", points = { { {{ motion.settle.0 }}, {{ motion.settle.1 }} }, { {{ motion.settle.2 }}, {{ motion.settle.3 }} } } })
hl.curve("sink",   { type = "bezier", points = { { {{ motion.sink.0 }}, {{ motion.sink.1 }} },   { {{ motion.sink.2 }}, {{ motion.sink.3 }} } } })
hl.curve("linear", { type = "bezier", points = { { 0, 0 }, { 1, 1 } } })

-- speed is in deciseconds
hl.animation({ leaf = "windowsIn",    enabled = true, speed = {{ motion.open | div(100) }},       bezier = "bloom",  style = "popin 94%" })
hl.animation({ leaf = "windowsOut",   enabled = true, speed = {{ motion.close | div(100) }},      bezier = "sink",   style = "popin 96%" })
hl.animation({ leaf = "windowsMove",  enabled = true, speed = {{ motion.move | div(100) }},       bezier = "settle" })
hl.animation({ leaf = "fadeIn",       enabled = true, speed = {{ motion.open | div(100) }},       bezier = "bloom" })
hl.animation({ leaf = "fadeOut",      enabled = true, speed = {{ motion.close | div(100) }},      bezier = "sink" })
hl.animation({ leaf = "fadeSwitch",   enabled = true, speed = {{ motion.focus | div(100) }},      bezier = "bloom" })
hl.animation({ leaf = "border",       enabled = true, speed = {{ motion.focus | div(100) }},      bezier = "bloom" })
hl.animation({ leaf = "borderangle",  enabled = true, speed = {{ motion.border_loop | div(100) | min(100) }}, bezier = "linear", style = "loop" })
hl.animation({ leaf = "workspaces",   enabled = true, speed = {{ motion.workspace | div(100) }},  bezier = "bloom",  style = "slidefade 20%" })
hl.animation({ leaf = "specialWorkspace", enabled = true, speed = {{ motion.scratchpad | div(100) }}, bezier = "bloom", style = "slidefadevert 20%" })
-- Quickshell animates its own panels; Hyprland only fades unknown layers
hl.animation({ leaf = "layers",       enabled = true, speed = 3, bezier = "bloom", style = "fade" })

---------------------------------------------------------------------------
-- Styling the base layer's window tags
---------------------------------------------------------------------------
-- forced opaque: browsers, video, images, editors, games
hl.window_rule({ name = "nacre-opaque", match = { tag = "opaque" }, opacity = "1.0 override 1.0 override" })
-- glassy: terminals, files, music, system tools stay a little see-through
hl.window_rule({ name = "nacre-glassy", match = { tag = "glassy" }, opacity = "{{ opacity.active }} override {{ opacity.inactive }} override" })
-- floating dialogs: rounder
hl.window_rule({ name = "nacre-dialog", match = { tag = "dialog" }, rounding = 20 })
-- picture-in-picture: no border
hl.window_rule({ name = "nacre-pip", match = { tag = "pip" }, border_size = 0, no_shadow = true })
-- fullscreen: no border or rounding
hl.window_rule({ name = "nacre-fullscreen", match = { fullscreen = true }, border_size = 0, rounding = 0 })
-- games: no animations, blur or shadow; always opaque
hl.window_rule({
    name = "nacre-game", match = { tag = "game" },
    no_anim = true, no_blur = true, no_shadow = true, opacity = "1.0 override 1.0 override",
})

---------------------------------------------------------------------------
-- Quickshell surfaces: real frosted glass behind the panels
---------------------------------------------------------------------------
hl.layer_rule({
    name = "nacre-glass", match = { namespace = "^nacre-(bar|launcher|notifs|center|osd|power|toast|keys|lock)$" },
    blur = true, ignore_alpha = 0.2, no_anim = true,
})
hl.layer_rule({ name = "nacre-wallpaper", match = { namespace = "^nacre-wallpaper$" }, no_anim = true })
